vity&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt; and trading technology agreements; and&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;other commercial agreements supporting the trading business.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;Providing&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt; pragmatic advice on market structure, trading regulation, market &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;conduct&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt; and legal risk affecting the European trading business.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;Working closely with &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;our c&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;ompliance and &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;r&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;isk &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;teams &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;to develop &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;practical solutions that appropriately balance business &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;objectives&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt; and legal risk.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;Supporting strategic projects, including new market launches, legal entity &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;expansions,&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt; and &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;growth initiatives.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
